"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisCtaContent } from "./components/cta-sections/content";
import View4 from "./components/cta-sections/variants/05-proof-orbit";
const views={"proof-orbit":View4};
export type { ArtemisCtaContent, ArtemisCtaImage, ArtemisCtaLink, ArtemisCtaQuestion, ArtemisCtaStat } from "./components/cta-sections/content";
export interface ArtemisCtaSectionsProps{className?:string;variant?:"proof-orbit"; /** The words on the CTA section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisCtaContent>; }
export function ArtemisCtaSections({className,variant="proof-orbit",content}:ArtemisCtaSectionsProps){const View=views[variant];return <ArtemisScope className={className}><View content={content}/></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisCtaLink {
  label: string;
  href: string;
}

/** A picture, and the words that describe it. */
export interface ArtemisCtaImage {
  src: string;
  /** What the picture shows; empty for a purely decorative one. */
  alt: string;
}

/** A figure with a short label under it. */
export interface ArtemisCtaStat {
  /** The figure as text, such as "120" or "4.9". Its digits roll into place. */
  value: string;
  /** Shown right after the figure, such as "K+" or "/5". */
  suffix?: string;
  /** What the figure counts. */
  label: string;
}

/** A question and its answer. */
export interface ArtemisCtaQuestion {
  question: string;
  answer: string;
  /** A short id, unique in the list, used in the row's element ids. Defaults to the row's position. */
  id?: string;
}

/** The words on an Artemis CTA section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisCtaContent {
  /** The short line above the heading. sunflower, product-window, proof-orbit, shade-panel, glow and terminal. */
  badge?: string;
  /** The heading. All layouts. */
  headline: string;
  /** The heading's second part. glow shows it on a line of its own in a muted tone; faq, terminal and split start a new line for it; the other layouts run it on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** The paragraph under the heading. All layouts. */
  subhead: string;
  /** The main button. All layouts. */
  cta: ArtemisCtaLink;
  /** A second button. floating-gallery, portrait-frame, glow, terminal and split. */
  secondaryCta?: ArtemisCtaLink;
  /** A quiet text link under the buttons. split. */
  link?: ArtemisCtaLink;
  /** A short line near the buttons. sunflower, portrait-frame, proof-orbit and glow. */
  note?: string;
  /** The picture beside the words. portrait-frame, which also blurs it behind the panel, and glow. */
  image?: ArtemisCtaImage;
  /** Photos floating at the sides. floating-gallery: up to six, in pairs from the top, left then right; under 768px wide only the first two show. */
  images?: ArtemisCtaImage[];
  /** Faces in a row above the words. proof-orbit: up to five, from the left; the third is the largest. */
  avatars?: ArtemisCtaImage[];
  /** What the row of faces shows, read by screen readers. proof-orbit. Left out, it keeps the layout's own only when `avatars` is left out too. */
  avatarsLabel?: string;
  /** Figures under the buttons. floating-gallery; four look best. */
  stats?: ArtemisCtaStat[];
  /** Short facts along the foot of the panel. glow. */
  highlights?: string[];
  /** An install command with a copy button. terminal types it out; split shows it on its button. */
  command?: string;
  /** The lines the terminal prints after `command`. terminal. Left out, it keeps the layout's own lines only when `command` is left out too. */
  commandOutput?: string[];
  /** Questions with answers that open one at a time; the first starts open. faq. */
  questions?: ArtemisCtaQuestion[];
}

"use client";
// @zeus-internal
import { MotionConfig, motion, type Transition, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import type { ArtemisCtaContent } from "../content";
const DEFAULT = {
    avatars: [
        { src: "/assets/artemis/a5badc559b706aa529b9.svg", alt: "Robin Ellis, Design lead" },
        { src: "/assets/artemis/327d06eee6b741023403.svg", alt: "Sam Brooks, Product engineer" },
        { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "Taylor Reed, Founder" },
        { src: "/assets/artemis/327d06eee6b741023403.svg", alt: "Quinn Wells, Creative director" },
        { src: "/assets/artemis/a5badc559b706aa529b9.svg", alt: "Morgan Ellis, Frontend lead" },
    ],
    avatarsLabel: "Built for cross-functional product teams",
    badge: "Designers \u00B7 founders \u00B7 builders",
    headline: "Join teams shipping work they are proud to show.",
    subhead: "Start with polished foundations, adapt every detail, and move from first pass to finished product faster.",
    cta: { label: "See what you can build", href: "#" },
    note: "Source included from day one",
} satisfies ArtemisCtaContent;
/** The size and offset of each face, from the left. */
const SLOTS = [
    "art:relative art:shrink-0 art:rounded-full art:border art:border-border art:p-1 art:size-11 art:translate-y-4",
    "art:relative art:shrink-0 art:rounded-full art:border art:border-border art:p-1 art:size-14 art:translate-y-1",
    "art:relative art:shrink-0 art:rounded-full art:border art:p-1 art:size-20 art:-translate-y-2 art:z-10 art:border-foreground/30",
    "art:relative art:shrink-0 art:rounded-full art:border art:border-border art:p-1 art:size-14 art:translate-y-1",
    "art:relative art:shrink-0 art:rounded-full art:border art:border-border art:p-1 art:size-11 art:translate-y-4",
] as const;
const IN_VIEW = { once: true } as const;
const INSTANT: Transition = { duration: 0 };
const reveal = (duration: number, delay = 0): Transition => ({ duration, delay, ease: ARTEMIS_EASE_OUT });
const bob = (i: number): Transition => ({ duration: 4.5 + 0.25 * i, ease: "easeInOut", repeat: Infinity });
const bobY = (i: number): number[] => [0, i % 2 === 0 ? -3 : 3, 0];
export default function CtaSectionsProofOrbit({ content }: { content?: Partial<ArtemisCtaContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const avatarsLabel = content?.avatars === undefined ? copy.avatarsLabel : content.avatarsLabel;
    const reduce = useReducedMotion();
    return (<MotionConfig reducedMotion="user">
      <div className="art:w-full">
        <section className="art:relative art:w-full art:overflow-hidden art:px-4 art:py-24 art:@min-[640px]/artemis:px-8">
          <div className="art:relative art:mx-auto art:flex art:w-full art:max-w-3xl art:flex-col art:items-center art:text-center">
            <motion.ul className="art:flex art:h-24 art:items-center art:justify-center art:-space-x-2 art:@min-[640px]/artemis:h-28 art:@min-[640px]/artemis:-space-x-1" aria-label={avatarsLabel} initial={{ opacity: 0, scale: 0.96, y: 14 }} whileInView={{ opacity: 1, scale: 1, y: 0 }} viewport={IN_VIEW} transition={reduce ? INSTANT : reveal(0.7)}>
              {copy.avatars.slice(0, SLOTS.length).map((avatar, i) => (<motion.li key={i} className={SLOTS[i]} animate={{ y: bobY(i) }} transition={bob(i)}>
                  <img src={avatar.src} alt={avatar.alt} className="art:size-full art:rounded-full art:object-cover art:grayscale"/>
                </motion.li>))}
            </motion.ul>
            <motion.p className="art:mt-4 art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest" initial={{ opacity: 0 }} whileInView={{ opacity: 1 }} viewport={IN_VIEW} transition={reduce ? INSTANT : reveal(0.5, 0.08)}>
              {copy.badge}
            </motion.p>
            <motion.h2 className="art:mt-7 art:max-w-3xl art:text-pretty art:text-4xl art:font-medium art:leading-tight art:tracking-tight" initial={{ opacity: 0, y: 16, filter: "blur(6px)" }} whileInView={{ opacity: 1, y: 0, filter: "blur(0px)" }} viewport={IN_VIEW} transition={reduce ? INSTANT : reveal(0.65, 0.1)}>
              {copy.headlineAccent ? `${copy.headline} ${copy.headlineAccent}` : copy.headline}
            </motion.h2>
            <motion.p className="art:mt-5 art:max-w-xl art:text-pretty art:text-base art:text-muted-foreground art:leading-7" initial={{ opacity: 0, y: 12 }} whileInView={{ opacity: 1, y: 0 }} viewport={IN_VIEW} transition={reduce ? INSTANT : reveal(0.6, 0.18)}>
              {copy.subhead}
            </motion.p>
            <motion.div className="art:mt-8" initial={{ opacity: 0, y: 12 }} whileInView={{ opacity: 1, y: 0 }} viewport={IN_VIEW} transition={reduce ? INSTANT : reveal(0.6, 0.24)}>
              <motion.a whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full" href={copy.cta.href} tabIndex={0}>
                {copy.cta.label}
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-4" aria-hidden="true">
                  <path d="M5 12h14"/>
                  <path d="m12 5 7 7-7 7"/>
                </svg>
              </motion.a>
            </motion.div>
            <motion.p className="art:mt-5 art:inline-flex art:items-center art:gap-2 art:text-muted-foreground art:text-sm" initial={{ opacity: 0 }} whileInView={{ opacity: 1 }} viewport={IN_VIEW} transition={reduce ? INSTANT : reveal(0.5, 0.32)}>
              <span className="art:grid art:size-5 art:place-items-center art:rounded-full art:border art:border-border">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:size-3" aria-hidden="true">
                  <path d="M20 6 9 17l-5-5"/>
                </svg>
              </span>
              {copy.note}
            </motion.p>
          </div>
        </section>
      </div>
    </MotionConfig>);
}
